      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n10/23~28) 만 40~49세 남성&여성 )주방용품 관련 온라인 커뮤니티 조사 (서울/수도권)\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.02. 17:24\n조회 83\n구독\n10/23~28) 만 40~49세 남성&여성 )주방용품 관련 온라인 커뮤니티 조사 (서울/수도권)\n10/23~28) 만 20~69세 남성&여성 )주방용품 관련 온라인 커뮤니티 조사 (서울/수도권)\n1. 대상\n서울/경기/인천 거주중인 만 20~69세 남성&여성\n주방용품을 본인이 직접 구매하여 사용하는 분\n최근 2년안에 프라이팬 또는 냄비를 새로 직접 구입하신 분\n주 1회 이상 직접 요리(원재료를 사서 직접 굽거나 끓이거나 조리하는)를 하는 분\n식품 저장용기 및 주방에서 쓰레기통 사용하는 분\n온라인 커뮤니티 참여 완료 후 후속 좌담회 및 가정방문 인터뷰도 가능한 분 (커뮤니티 참여자 중 일부 선정하여 진행 예정)\n2. 조사 방법 및 일정\n일정: 10/23~10/28 중 1~2일간 참여\n온라인 커뮤니티에 올라온 과제에 참여\n주제에 따라 사진/동영상 촬영하여 올리는 과제도 있음\n현재 사용하는 주방용품(프라이팬,냄비,저장용기,쓰레기통) 인증샷 제출 가능한 분\n온라인 커뮤니티 참여자중 일부 선정하여 후속 조사까지 참여 가능한 분 우선 선발예정\n3. 참여 사례비\n온라인 커뮤니티 참여 사례비: 3만원~5만원 (참여도에 따라 차등 지급)\n후속 조사(좌담회, 가정방문 인터뷰) 사례비는 해당 대상자에게 개별 안내 예정\n4. 신청방법\n아래 신청 버튼을 클릭하면 대상자 선정을 위한 신청페이지가 나옵니다.\n접속하여 설문응답 진행해주세요. 설문응답 첫 문항 소개자명에 [_____]를 필수로 기입해주세요.\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\nhttps://tally.so/r/68aGpo\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구의 더 많은 인기글 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.10.02. 18:17 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n10/23~28) 만 50~59세 남성&여성 )주방용품 관련 온라인 커뮤니티 조사 (서울/수도권)\n좌담회알바좌담회카페\n26.10.02.\n댓글\n1\n10/23~28) 만 40~49세 남성&여성 )주방용품 관련 온라인 커뮤니티 조사 (서울/수도권)\n좌담회알바좌담회카페\n26.10.02.\n댓글\n1\n10/23~28) 만 30~39세 남성&여성 )주방용품 관련 온라인 커뮤니티 조사 (서울/수도권)\n좌담회알바좌담회카페\n26.10.02.\n댓글\n1\n10/23~28) 만 20~29세 남성&여성 )주방용품 관련 온라인 커뮤니티 조사 (서울/수도권)\n좌담회알바좌담회카페\n26.10.02.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
