      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n공지\n안녕하세요~귀사에서 작성하신 폼으로 모집을 의뢰하실때는요~\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.02. 21:28\n조회 196\n구독\n안녕하세요~\n귀사에서 작성하신 폼으로 모집을 의뢰하실때는요~\n저희카페 고유링크인 경우: 소개자 적는칸이 없어도 됩니다만\n저희카페 고유링크가 아닌경우: 첫번째 칸에 소개자이름 적는칸을 만들어서\n보내주시면 바로 공지하겠습니다\n뒤에 있으면 확인을 위해 질문에 테스트 하는 사이 탈락하면 확인을 못합니다ㅠㅠ\n그럴경우 공지할수가 없으니 양해 바랍니다 ㅠ\n위와같이 첫번째칸에 소개자 송난주에 필수항목으로 체크할수 있도록 질문 문항에 추가해서 보내주시면 확인하고 바로 공지하겠습니다~\n또는 송난주 고유링크로 설정이 되어있을때도 가능합니다~\n고유링크에 장점이 있습니다\n송난주 고유링크 설정은 담당자님이 작성하신 링크이기 때문에\n빛보다 빠른 확인이 가능하십니다^^\n따라서 일정이 급한 조사일때 빠르게 컨택 하실수 있습니다^^\n고유링크인 경우 : 링크 앞에 고유링크라고 기재해서 보내주시면 감사하겠습니다 ~\n또한\n고유링크가 아닌경우 : 첫번째 칸에 위와같이 소개자 이름 적는칸을 만들어서 보내주시면 감사하겠습니다 ~\n귀사의 무궁한 발전을 기원합니다 ~\n좋아요\n1\n좋아요한 사람 목록으로 이동\n'좋아요'로 마음을 나누세요!\n송파구 이웃끼리 공유하는 동네 꿀정보\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n어쩌면 괜찮은\n신입회원\nNew\n2026.10.02. 21:37 답글쓰기\n옵션\n좋아요\n1\n댓글을 남겨보세요\n전체글\n10/13) 30-54세 남녀)  키움증권 DC/IRP 보유자 대상 좌담회\n좌담회알바좌담회카페\n26.10.02.\n댓글\n0\n안녕하세요~귀사에서 작성하신 폼으로 모집을 의뢰하실때는요~\n좌담회알바좌담회카페\n26.10.02.\n댓글\n1\n10/19~22) 수도권 거주 25-59세 여성 ) 000명 조사\n좌담회알바좌담회카페\n26.10.02.\n댓글\n0\n10/19~22) 수도권 거주 25-59세 남성 ) 000명 조사\n좌담회알바좌담회카페\n26.10.02.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
